import vm from 'node:vm';

export function workerEntry(source) {
  // The source declaration is a JSON-compatible list of local script paths.
  const entry = /^importScripts\(([^;\r\n]*)\);[ \t]*(?:\r?\n|$)/.exec(source);
  if (!entry) throw new Error('WORKER_DEPENDENCIES_MISSING');
  const dependencies = JSON.parse(`[${entry[1]}]`);
  if (!dependencies.length || new Set(dependencies).size !== dependencies.length ||
      dependencies.some(p => typeof p !== 'string' || !/^lib\/(?:[\w-]+\/)*[\w-]+\.js$/.test(p)))
    throw new Error('WORKER_DEPENDENCIES_INVALID');
  return { dependencies, body: source.slice(entry[0].length) };
}

export async function bundleWorker(source, readSource) {
  const { dependencies, body } = workerEntry(source);
  const scripts = await Promise.all(dependencies.map(async p => `// ${p}\n${await readSource(p)}`));
  const bundle = '// GENERATED by tools/build.mjs. Edit background.js and its source modules instead.\n' +
    [...scripts, `// background.js\n${body}`].join('\n;\n');
  new vm.Script(bundle, { filename: 'background-worker.js' });
  return bundle;
}
